package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;

/** The due-by a new claim gets, fixed when it is created; a claim belongs to the period holding its due-by. */
public final class DueBy {

    private DueBy() {
    }

    /** The due-by of a new claim of the person dated on the date: the date plus the person's own terms (else the
     *  terms of their grade in force on the date (else the sheet's terms in force on it)). */
    public static LocalDate of(Person person, LocalDate date, SettingRepository settings) {
        return date.plusDays(person.terms() != null ? person.terms()
                : settings.termsFor(person.sheetId(), person.grades().on(date), date));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Store the new claim under the person; with no date given it is dated the sheet's entry date, else its today. Its due-by is fixed now:
 *  its date plus the person's own terms (else the terms of the person's grade in force on its date (else the sheet's terms in force on its date)). Its DRAFT line starts its status log. Due by inside a soft-closed period, it is a late entry. */
public class SaveNewClaim {
    public void save(@Val ClaimInput input, @Val Person person, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log, Out<Claim> claim) {
        claim.set(insert(input, person, sheets, settings, periods, repository, log));
    }

    /** Store one new claim as the claim form does (the paste box stores each of its lines this way). */
    static Claim insert(ClaimInput input, Person person, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log) {
        var date = input.date() != null ? input.date() : sheets.newClaimDate(person.sheetId());
        var dueBy = DueBy.of(person, date, settings);
        Claim added = repository.insert(new Claim(0, person.sheetId(), person.id(), input.amount(), date, input.note(),
                ClaimStatus.DRAFT, null, null, null, false, null, input.corrects(), dueBy, null, 0, null,
                periods.softClosedOn(person.sheetId(), dueBy) != null, null));
        log.record(added, input.user());
        return added;
    }
}
package net.officefloor.hq.app.claim;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.ClosedPeriodException;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Check every pasted line against the sheet first, as the claim form would for its person: the name must be on
 *  the sheet (compared as names are), the claim not dated (a blank date being the sheet's entry date, else its today) after the person's
 *  retirement date nor due by (its date plus the terms it would get) inside a closed period. Any failure refuses the whole paste, naming the line, and nothing
 *  is written. Otherwise each line is added in order as a DRAFT claim, just as the claim form adds one: its
 *  CLAIM_ADDED line and then how the sheet's figures moved over it. */
public class PasteClaims {
    public void paste(@PathVariable("sheetId") String sheetId, @Val PasteInput input, PersonRepository people,
            SheetRepository sheets, SettingRepository settings, PeriodRepository periods, ClaimRepository claims,
            ClaimLogRepository log, Rollups rollups, Audit audit, Out<PasteResponse> result)
            throws InvalidClaimException {
        String sheet = sheetId.trim();
        periods.lockSheet(sheet);
        List<Person> owners = new ArrayList<>();
        for (PasteLine line : input.lines()) {
            Person person = people.findByName(sheet, line.name());
            if (person == null) {
                throw new InvalidClaimException("Line " + line.number() + ": " + line.name() + " is not on the sheet.");
            }
            var date = line.claim().date() != null ? line.claim().date() : sheets.newClaimDate(sheet);
            try {
                RetiredPersonException.refuse(person, date);
            } catch (RetiredPersonException e) {
                throw new InvalidClaimException("Line " + line.number() + ": " + e.getMessage());
            }
            Period closed = periods.closedOn(sheet, DueBy.of(person, date, settings));
            if (closed != null) {
                throw new InvalidClaimException("Line " + line.number() + ": " + new ClosedPeriodException(closed).getMessage());
            }
            owners.add(person);
        }
        for (int i = 0; i < owners.size(); i++) {
            ClaimInput claim = input.lines().get(i).claim();
            Person person = owners.get(i);
            Rollup before = rollups.take(sheet);
            Claim added = SaveNewClaim.insert(claim, person, sheets, settings, periods, claims, log);
            AuditClaimAdded.record(claim, person, added, audit);
            rollups.record(sheet, input.user(), before);
        }
        result.set(new PasteResponse(owners.size()));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Split an amount off the loaded claim: only an OPEN claim not deferred on the sheet's today, and only an amount
 *  less than the claim's. The claim keeps the rest of its amount and loses any figure a statement bound it to; a new
 *  OPEN claim with the split-off amount, the same person, date and note, the next number, opened by the user, its
 *  due-by fixed now from the terms in force on its date (as a new claim's is) and the claim's number as its
 *  split-from is stored (a late entry when that due-by is inside a soft-closed period), its OPEN line starting its status log. A split another user's change got to first is
 *  refused. */
public class SaveSplit {
    public void save(@Val SplitInput input, @Val Claim loaded, SheetRepository sheets, SettingRepository settings,
            PersonRepository people, PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log, Out<Split> split,
            Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException, InvalidClaimException {
        if (loaded.status() != ClaimStatus.OPEN) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be split; only an OPEN one can.");
        }
        var today = sheets.today(loaded.sheetId());
        if (loaded.deferredOn(today)) {
            throw new ClaimStatusNotAllowedException("This claim is deferred until " + loaded.deferredUntil()
                    + "; it cannot be split.");
        }
        if (input.amount().compareTo(loaded.amount()) >= 0) {
            throw new InvalidClaimException("The amount to split off must be less than the claim's "
                    + loaded.amount().toPlainString() + ".");
        }
        var rest = loaded.amount().subtract(input.amount());
        if (!repository.splitRest(loaded, rest)) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        var person = people.find(loaded.sheetId(), loaded.personId());
        var dueBy = DueBy.of(person, loaded.date(), settings);
        Claim inserted = repository.insert(new Claim(0, loaded.sheetId(), loaded.personId(), input.amount(),
                loaded.date(), loaded.note(), ClaimStatus.DRAFT, null, null, null, false, null, null, dueBy, null, 0,
                loaded.number(), periods.softClosedOn(loaded.sheetId(), dueBy) != null, null));
        String number = repository.nextNumber(loaded.sheetId(), dueBy);
        repository.changeStatus(inserted, ClaimStatus.OPEN, number, null, input.user());
        log.record(inserted, input.user());
        Claim original = new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), rest, loaded.date(),
                loaded.note(), loaded.status(), loaded.number(), loaded.settledDue(), loaded.openedBy(), false, null,
                loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(), loaded.proofs(), loaded.splitFrom(), loaded.lateEntry(), loaded.reminded());
        Claim added = repository.find(loaded.sheetId(), inserted.id());
        split.set(new Split(original, added));
        saved.set(ClaimResponse.from(added, List.of(), today));
    }
}
package net.officefloor.hq.app.quickadd;

import net.officefloor.hq.app.person.AuditPersonAdded;
