import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';

/** A steward's delegation of the steward role to a user, from a from-date to a to-date (both included). */
export type Delegation = { id: number; user: string; from: string; to: string; by: string };

export const delegationsKey = (sheetId: string) => ['sheet', sheetId, 'delegations'] as const;

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** The sheet's delegations and the form a steward delegates the steward role with. While the sheet's today is
 *  inside a delegation's dates its user acts as a steward. */
function Delegations({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const delegations = useQuery({
    queryKey: delegationsKey(sheetId),
    queryFn: () => getJson<Delegation[]>(`/api/sheets/${encodeURIComponent(sheetId)}/delegations`),
  }).data ?? [];
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (body: { name: string; from: string; to: string }) =>
      postJson<Delegation>(`/api/sheets/${encodeURIComponent(sheetId)}/delegations`, { user, ...body }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: delegationsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not delegate the steward role.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (name.trim() === '') {
      setError('Give the user name the steward role is delegated to.');
      return;
    }
    if (!DATE.test(from.trim()) || !DATE.test(to.trim())) {
      setError('The from- and to-dates must be dates (yyyy-mm-dd).');
      return;
    }
    if (to.trim() < from.trim()) {
      setError("The delegation's to-date must not be before its from-date.");
      return;
    }
    if (!once.start()) return;
    save.mutate({ name: name.trim(), from: from.trim(), to: to.trim() });
  };

  const change = (set: (v: string) => void) => (e: { target: { value: string } }) => {
    set(e.target.value);
    setError('');
  };

  return (
    <section data-testid="delegations">
      <h2>Delegations</h2>
      <form data-testid="delegate-form" onSubmit={submit}>
        <input data-testid="delegate-user" placeholder="User name" value={name} onChange={change(setName)} />{' '}
        <input data-testid="delegate-from" placeholder="from yyyy-mm-dd" value={from} onChange={change(setFrom)} />{' '}
        <input data-testid="delegate-to" placeholder="to yyyy-mm-dd" value={to} onChange={change(setTo)} />{' '}
        <button type="submit" data-testid="delegate-submit" disabled={save.isPending}>
          Delegate steward
        </button>
        {error && (
          <p data-testid="delegate-error" role="alert">
            {error}
          </p>
        )}
      </form>
      <p>Only a steward can delegate. The user acts as a steward while the sheet's today is inside the dates.</p>
      <ul>
        {delegations.map((d) => (
          <li key={d.id} data-testid="delegate-line">
            {d.user} acts as steward for {d.by} from {d.from} to {d.to}
          </li>
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 9, Component: Delegations });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { defineSlot } from '../Slot';

/**
 * The loaded sheet's body. Every feature kept per sheet contributes here; the home page renders it
 * only once someone is signed in and a sheet is loaded. Server data under a sheet is keyed
 * ['sheet', sheetId, ...] so a sheet load re-reads all of it.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx response: its status and the text the server sent with it. */
export class HttpError extends Error {
  constructor(
    message: string,
    readonly status: number,
    readonly body: string,
  ) {
    super(message);
  }
}

/** The date this screen shows the sheet as of ('' when it shows it as it is now): every read asks for the sheet as
 *  of it (?asOf=), and every change is sent marked with it (X-As-Of), so the server refuses it. Kept in step with
 *  the URL's asOf by features/sheet/asof; read from the URL at start-up so the first reads already carry it. */
let asOf = typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get('asOf') ?? '';

export function setRequestAsOf(date: string): void {
  asOf = date;
}

function withAsOf(path: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}

function changeHeaders(): Record<string, string> {
  return asOf === '' ? { 'Content-Type': 'application/json' } : { 'Content-Type': 'application/json', 'X-As-Of': asOf };
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status, await res.text());
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(withAsOf(path));
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: changeHeaders(),
    body: JSON.stringify(body),
  });
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's patron: another person on the same sheet (by id). */
export type Patron = { personId: number; patronId: number };

export const patronsKey = (sheetId: string) => ['sheet', sheetId, 'patrons'] as const;

