package net.officefloor.hq.app.person;

import java.util.List;

/** A person as the screen shows them, with their grade in force on the sheet's today, their statement count and
 *  the last statement's due-total (two decimals; null when n/a, or none taken) and date (yyyy-mm-dd; null when none
 *  taken), the date they are retired from (yyyy-mm-dd; null: not retired), whether they have any hold, their dated
 *  grades, earliest first (each from its from-date, yyyy-mm-dd; null: from the beginning of time), and their holds
 *  in the order they were put on (from- and to-date, yyyy-mm-dd; null: unbounded on that side), and their own terms in days (null: none). */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeResponse> grades,
        List<HoldResponse> holds, Integer terms) {

    /** A grade given from a from-date (yyyy-mm-dd; null: from the beginning of time). */
    public record GradeResponse(String grade, String from) {
    }

    /** A hold from a from-date to a to-date (yyyy-mm-dd; null: unbounded on that side). */
    public record HoldResponse(String from, String to) {
    }

    public static PersonResponse from(Person p) {
        return new PersonResponse(p.id(), p.name(), p.grade(), p.version(), p.statementCount(),
                p.statedTotal() != null ? p.statedTotal().toPlainString() : null,
                p.statementDate() != null ? p.statementDate().toString() : null,
                p.retiredFrom() != null ? p.retiredFrom().toString() : null, p.holds().any(),
                p.grades().history().stream()
                        .map(g -> new GradeResponse(g.grade(), g.from() != null ? g.from().toString() : null)).toList(),
                p.holds().history().stream().map(h -> new HoldResponse(h.from() != null ? h.from().toString() : null,
                        h.to() != null ? h.to().toString() : null)).toList(), p.terms());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded person and store it, refused when the person has been saved since
 *  the version the edit was made from. The grade is recorded from the edit's from-date (the sheet's today
 *  when none was given), keeping the grades already recorded from other dates. The person's own terms are set when the edit gives
 *  them (cleared when given blank). */
public class SavePerson {
    public void save(@Val PersonRequest request, @Val Person loaded, PersonRepository repository,
            SheetRepository sheets, Out<PersonResponse> saved) throws StalePersonException {
        long from = request.version() == null ? loaded.version() : request.version();
        Person person = new Person(loaded.id(), loaded.sheetId(), request.name(), loaded.grade(), from + 1,
                loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(), loaded.retiredFrom(),
                loaded.grades(), loaded.holds(), loaded.terms());
        if (!repository.update(person, from)) {
            throw new StalePersonException(loaded.name());
        }
        LocalDate gradeFrom = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom())
                : sheets.today(loaded.sheetId());
        repository.grade(person, request.grade(), gradeFrom);
        if (request.terms() != null) {
            repository.terms(person, request.terms().isEmpty() ? null : Integer.valueOf(request.terms()));
        }
        saved.set(PersonResponse.from(repository.find(loaded.sheetId(), loaded.id())));
    }
}

